import {readFile} from 'node:fs/promises';import {createHash} from 'node:crypto';const origin='https://brownnoodyai-sketch.github.io',paths=['index.html','item.html','index.mjs','item.mjs','listing.mjs','website-data.mjs','website-data.json','copy.mjs','design.mjs','designer.mjs','designer.html','studio.html','studio-builder.html','studio-builder.mjs','zip.mjs'];const digest=b=>createHash('sha256').update(b).digest('hex'),expected=new Map(await Promise.all(paths.map(async p=>[p,digest(await readFile(p))])));let problem='not ready';for(let a=1;a<=24;a++){try{await Promise.all(paths.map(async p=>{const r=await fetch(origin+'/'+p+'?release='+(process.env.GITHUB_SHA||'verify')+'&a='+a,{cache:'no-store',redirect:'error',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error(p+' '+r.status);if(p.endsWith('.mjs')&&!/javascript|ecmascript/i.test(r.headers.get('content-type')||''))throw Error(p+' MIME');if(digest(Buffer.from(await r.arrayBuffer()))!==expected.get(p))throw Error(p+' mismatch');}));console.log(JSON.stringify({websitePublished:true,url:origin+'/',assets:paths.length}));process.exit(0);}catch(e){problem=e.message;if(a<24)await new Promise(r=>setTimeout(r,10000));}}console.error(problem);process.exitCode=1;
